mapper.select:
SELECT a.NTT_SJ, a.NTCR_ID, a.NTCR_NM, a.NTT_NO, a.NTT_CN, a.PASSWORD, a.FRST_REGISTER_ID, b.USER_NM as FRST_REGISTER_NM,
TO_CHAR(a.FRST_REGIST_PNTTM, 'YYYY-MM-DD HH24:MI') as FRST_REGIST_PNTTM, a.NTCE_BGNDE, a.NTCE_ENDDE, a.RDCNT, a.USE_AT, a.ATCH_FILE_ID, a.BBS_ID, a.NTT_ID, a.SJ_BOLD_AT, a.NOTICE_AT, a.SECRET_AT, a.PARNTSCTT_NO, a.ANSWER_AT, a.ANSWER_LC, a.SORT_ORDR, a.NTT_EXTRA_FIELD_1, a.NTT_EXTRA_FIELD_2, a.NTT_EXTRA_FIELD_3, a.NTT_EXTRA_FIELD_4, a.NTT_EXTRA_FIELD_5, a.NTT_EXTRA_FIELD_6, a.NTT_EXTRA_FIELD_7, a.NTT_EXTRA_FIELD_8, a.NTT_EXTRA_FIELD_9, a.NTT_EXTRA_FIELD_10, c.BBS_TY_CODE, c.REPLY_POSBL_AT, c.FILE_ATCH_POSBL_AT, c.ATCH_POSBL_FILE_NUMBER, c.BBS_NM FROM COMTNBBS a LEFT OUTER JOIN COMVNUSERMASTER b ON a.FRST_REGISTER_ID = b.ESNTL_ID LEFT OUTER JOIN COMTNBBSMASTER c ON a.BBS_ID = c.BBS_ID WHERE a.BBS_ID = #{bbsId} AND a.NTT_ID = #{nttId}
AND a.USE_AT = 'Y'

mapper.update:
UPDATE COMTNBBS SET
	USE_AT = 'N',
	LAST_UPDUSR_ID = #{lastUpdusrId},
	LAST_UPDT_PNTTM = LOCALTIMESTAMP
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}

UPDATE COMTNBBS SET
	USE_AT = 'Y',
	LAST_UPDUSR_ID = #{lastUpdusrId},
	LAST_UPDT_PNTTM = LOCALTIMESTAMP
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}

mapper.select:

SELECT COALESCE(MAX(RDCNT),0)+1 AS RDCNT FROM COMTNBBS
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}

mapper.update:

UPDATE COMTNBBS SET 
	RDCNT = #{inqireCo},
	LAST_UPDUSR_ID = #{lastUpdusrId},
	LAST_UPDT_PNTTM = LOCALTIMESTAMP
WHERE BBS_ID = #{bbsId}
AND NTT_ID = #{nttId}

mapper.select:
SELECT NTT_ID, NTT_SJ, ATCH_FILE_ID FROM (
	SELECT a.NTT_ID, a.NTT_SJ, a.ATCH_FILE_ID
	FROM COMTNBBS a
	WHERE a.BBS_ID = #{bbsId}
	AND a.USE_AT = 'Y'
	AND COALESCE(a.SECRET_AT, 'N') != 'Y'
	AND a.NTT_ID  <  #{nttId}
	ORDER BY a.NTT_ID DESC
) X LIMIT 1

SELECT NTT_ID, NTT_SJ, ATCH_FILE_ID FROM (
	SELECT a.NTT_ID, a.NTT_SJ, a.ATCH_FILE_ID
	FROM COMTNBBS a
	WHERE a.BBS_ID = #{bbsId}
	AND a.USE_AT = 'Y'
	AND COALESCE(a.SECRET_AT, 'N') != 'Y'
	AND a.NTT_ID  >  #{nttId}
	ORDER BY a.NTT_ID ASC
) X LIMIT 1
